CREATE TABLE `tenancy_audit_events` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`workspace_id` CHAR(36) CHARACTER SET ascii NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`action` VARCHAR(80) CHARACTER SET ascii NOT NULL,`resource_type` VARCHAR(64) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`occurred_at` DATETIME(3) NOT NULL,`schema_version` SMALLINT UNSIGNED NOT NULL,PRIMARY KEY(`id`),KEY `idx_tenancy_audit_org_time`(`organization_id`,`occurred_at`),KEY `idx_tenancy_audit_trace`(`trace_id`),CONSTRAINT `fk_tenancy_audit_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_tenancy_audit_actor` FOREIGN KEY(`actor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
